/**
 * Type guard for studio join shape from studio_members queries.
 * Centralizes the type-narrowing pattern used across app/(app)/layout.tsx
 * and dashboard/page.tsx (#76).
 */
export interface JoinedStudio {
  id: string
  name: string
  slug: string
  logo_url: string | null
  plan_id: string | null
}

export function isJoinedStudio(v: unknown): v is JoinedStudio {
  return (
    typeof v === 'object' &&
    v !== null &&
    'name' in v &&
    'id' in v &&
    typeof (v as Record<string, unknown>).name === 'string' &&
    typeof (v as Record<string, unknown>).id === 'string'
  )
}
